states.5379df53232a:
{
 "case_summary": {
  "complaint_ref": "CWB-COMP-24-31907",
  "bank": "Calder & Wye Bank plc (CRM Code signatory)",
  "customer": "Mr Nikhil Rathore, 52, pharmacist, Leicester",
  "scheme": "12-month 'bridging loan note' from Ashdown Bridging Partners Ltd, sold by its director Conrad Vale: 18% a year, fixed and guaranteed, said to be secured on a housing development in Solihull and backed by Mr Vale's personal guarantee. Mr Rathore's cousin told him he had already received £3,600 in interest from the same scheme.",
  "status": "Bank declined the claim on 22 August 2024; complaint now with the Financial Ombudsman Service; investigator's view: not upheld."
 },
 "payments": [
  {
   "date": "2024-06-10 10:31",
   "amount": "£20,000.00",
   "payee": "C Vale (personal account)",
   "method": "Faster Payment"
  },
  {
   "date": "2024-06-11 08:47",
   "amount": "£20,000.00",
   "payee": "C Vale (personal account)",
   "method": "Faster Payment"
  },
  {
   "date": "2024-06-13 12:05",
   "amount": "£15,000.00",
   "payee": "C Vale (personal account)",
   "method": "Faster Payment"
  }
 ],
 "online_banking_audit_2024_06_10": [
  "09:14 New payee 'C Vale' added. Purpose selected: 'Making an investment'. Investment-scam warning shown: 'Fraudsters offer what looks like a genuine opportunity with high or guaranteed returns. Check the firm is on the FCA register before you pay.' Payment cancelled by customer at 09:16.",
  "09:24 Payment re-entered to 'C Vale'. Purpose selected: 'Buying goods or services'. Purchase-scam warning shown. Customer proceeded.",
  "09:25 Payment held for a fraud check."
 ],
 "fraud_call_2024_06_10": [
  {
   "speaker": "agent",
   "text": "Can you tell me what this £20,000 is for?"
  },
  {
   "speaker": "customer",
   "text": "I'm buying a classic car, a 1972 Jaguar E-type, from a friend of my cousin. I've seen it, it's in his garage in Kenilworth."
  },
  {
   "speaker": "agent",
   "text": "Has anyone asked you to tell us a particular story, or told you not to tell us what the payment is really for?"
  },
  {
   "speaker": "customer",
   "text": "No, nobody. It's my money and it's a car."
  },
  {
   "speaker": "agent",
   "text": "Thank you. Fraudsters sometimes pretend to be from your bank and ask you to move money to a 'safe account', and others intercept e-mails and change bank details on invoices. If anything like that has happened, stop. I'll release the payment now."
  }
 ],
 "whatsapp_with_vale": [
  {
   "time": "2024-06-10 09:18",
   "from": "Mr Rathore",
   "text": "Bank put a scam warning up when I chose investment. What do I put?"
  },
  {
   "time": "2024-06-10 09:20",
   "from": "Conrad Vale",
   "text": "Put goods/services and say it's a car if they ring. Banks hate private lending, they'll block you just to keep your money. They're the real crooks."
  },
  {
   "time": "2024-06-10 10:35",
   "from": "Mr Rathore",
   "text": "Done, they bought the car story. First 20 is on its way."
  },
  {
   "time": "2024-06-12 19:02",
   "from": "Mr Rathore",
   "text": "If Calder give me grief tomorrow I'll send the last bit from my other bank, they never ask questions."
  }
 ],
 "investigator_view_extract": "Mr Rathore didn't have a reasonable basis for believing the investment was genuine: a guaranteed 18% a year was too good to be true, the money went to the director's personal account rather than a company account, he made no checks of his own beyond his cousin's account, and he was told to give his bank a false reason. Calder & Wye's warnings were not tailored to investment scams, so I don't think it gave an Effective Warning. But I'm not persuaded a better warning would have made a material difference, because Mr Rathore was hiding the real purpose on Mr Vale's instructions and was prepared to use another bank. I don't uphold the complaint.",
